func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket", basket != null, "La scena basket.tscn deve avviarsi correttamente"):
		return
	if not check("has_func", has_function(basket, "spawn_stars"), "Il cesto deve contenere la funzione spawn_stars"):
		return
	var stars: Array[Node] = []
	for child in basket.get_children():
		if child is Sprite2D and child.get_script() != null:
			var script_path: String = child.get_script().resource_path
			if "star.gd" in script_path:
				stars.append(child)
	if not check("star_count", stars.size() == 5, "Devono essere create esattamente 5 stelle all'avvio"):
		return
	var s0: Sprite2D = stars[0] as Sprite2D
	var s1: Sprite2D = stars[1] as Sprite2D
	check("first_x", is_equal_approx(s0.position.x, 120.0), "La prima stella deve avere coordinata X uguale a 120.0")
	check("spacing_x", is_equal_approx(s1.position.x - s0.position.x, 220.0), "Lo scostamento orizzontale tra le stelle deve essere di 220.0 pixel")
	check("first_y", is_equal_approx(s0.position.y, 80.0), "La prima stella deve trovarsi ad altezza Y pari a 80.0")

